#!/usr/bin/env python3
"""Generate deploy/base/opa/configmap-policy.yaml from policy/*.rego (the single source of truth).

`--check` exits non-zero if the committed file is stale (used by CI). Test files are excluded.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "deploy/base/opa/configmap-policy.yaml"


def render() -> str:
    lines = [
        "# GENERATED by scripts/gen_opa_configmap.py from policy/*.rego. Do not edit by hand.",
        "apiVersion: v1",
        "kind: ConfigMap",
        "metadata:",
        "  name: opa-policy",
        "data:",
    ]
    for f in sorted((ROOT / "policy").glob("*.rego")):
        if f.name.endswith("_test.rego"):
            continue
        lines.append(f"  {f.name}: |")
        lines.extend(("    " + ln) if ln else "" for ln in f.read_text().splitlines())
    return "\n".join(lines) + "\n"


def main() -> int:
    text = render()
    if "--check" in sys.argv:
        if not OUT.exists() or OUT.read_text() != text:
            print(
                f"{OUT.relative_to(ROOT)} is stale; run scripts/gen_opa_configmap.py",
                file=sys.stderr,
            )
            return 1
        return 0
    OUT.write_text(text)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
